fn fibonacci(n: usize) -> Vec<i32> {
    // Since n >= 2 by assumption, we can safely initialize the first two fibonacci numbers.
    let mut fibs = Vec::with_capacity(n);
    fibs.push(0);
    fibs.push(1);

    for i in 2..n {
        // Safe to unwrap because fibs[i-1] and fibs[i-2] exist.
        // Also, assumption guarantees no overflow beyond i32 range.
        let next = fibs[i - 1] + fibs[i - 2];
        fibs.push(next);
    }

    fibs
}